sql_query:
SELECT "Type of therapy"
FROM clinical_trials
WHERE "Cancer type" = 'Melanoma' AND "Included in MA" = 'No' AND "Name of ICI" = 'Ipilimumab';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Type of therapy" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Melanoma' AND "Included in MA" = 'No' AND "Name of ICI" = 'Ipilimumab'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_is_combination(source_value) AS "is_combination"
FROM base;
